mapper.select:
select d.*, i.title as itemTitle, i.price as itemPrice, (select img.image_data from item_image img where img.item_id = d.item_id order by img.sort_no limit 1) as itemCover, b.nickname as buyerNickname, s.nickname as sellerNickname, (select count(*) from review r where r.item_id = d.item_id and r.reviewer_id = #{userId}) as reviewed from deal d left join item i on d.item_id = i.id left join `user` b on d.buyer_id = b.id left join `user` s on d.seller_id = s.id
and d.buyer_id = #{userId} and d.seller_id = #{userId}
and d.status = #{status}
order by d.created_at desc

select count(*) from deal d

    where d.buyer_id = #{userId}
    where d.seller_id = #{userId}

and d.status = 'PENDING'
